// app/products/[id]/page.tsx
import { notFound } from 'next/navigation';

export const revalidate = 3600; // safety net: refresh at most once an hour

export async function generateStaticParams() {
  const top = await fetch('https://api.shop.dev/products?top=1000').then(r => r.json());
  return top.map((p: { id: string }) => ({ id: p.id })); // the rest render on first visit
}

async function getProduct(id: string) {
  const res = await fetch(`https://api.shop.dev/products/${id}`, {
    cache: 'force-cache',
    next: { tags: [`product-${id}`] },
  });
  return res.ok ? res.json() : null;
}

export default async function Page({ params }: PageProps<'/products/[id]'>) {
  const { id } = await params; // params is a Promise in Next.js 16
  const product = await getProduct(id);
  if (!product) notFound();
  return <h1>{product.name} — {product.price}</h1>;
}

