'use client';
import { useEffect, useState } from 'react';

const utc = new Intl.DateTimeFormat('en-GB', {
  timeStyle: 'medium',
  timeZone: 'UTC',
});

export function LastUpdated({ iso }: { iso: string }) {
  // Server and first client render produce the SAME text (fixed zone).
  const [label, setLabel] = useState(() => utc.format(new Date(iso)) + ' UTC');

  useEffect(() => {
    // Runs only in the browser, after hydration: now local time is safe.
    setLabel(new Date(iso).toLocaleTimeString());
  }, [iso]);

  return <time dateTime={iso}>{label}</time>;
}

