'use server';
import { z } from 'zod';
import { updateTag } from 'next/cache';
import { auth } from '@/lib/auth';
import { db } from '@/lib/db'; // db.ts starts with: import 'server-only'

const Input = z.object({ postId: z.uuid() });

export async function deletePost(raw: unknown) {
  const session = await auth();
  if (!session) throw new Error('Unauthorized');

  const { postId } = Input.parse(raw); // never trust client input

  const post = await db.post.findUnique({
    where: { id: postId },
    select: { authorId: true },
  });
  if (!post || post.authorId !== session.user.id) throw new Error('Forbidden');

  await db.post.delete({ where: { id: postId } });
  updateTag(`posts-${session.user.id}`); // the author sees the change immediately
}

