'use client';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useSearchParams } from 'next/navigation';

type Order = { id: string; status: 'open' | 'done'; starred: boolean };

// fetch() does NOT reject on 4xx/5xx; without this check errors become “data”.
async function json<T>(res: Response): Promise<T> {
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json() as Promise<T>;
}

export function useOrders() {
  const status = useSearchParams().get('status') ?? 'open'; // URL state
  return useQuery({
    queryKey: ['orders', { status }],                        // every input is in the key
    queryFn: ({ signal }) =>
      fetch(`/api/orders?status=${encodeURIComponent(status)}`, { signal }).then(r => json<Order[]>(r)),
    staleTime: 30_000,                                        // fresh for 30 s, no refetch storm
  });
}

export function useToggleStar(status: string) {
  const qc = useQueryClient();
  const key = ['orders', { status }];
  return useMutation({
    mutationFn: async (id: string) => {
      const res = await fetch(`/api/orders/${id}/star`, { method: 'POST' });
      if (!res.ok) throw new Error(`HTTP ${res.status}`); // so onError (rollback) really runs
    },
    onMutate: async (id) => {
      await qc.cancelQueries({ queryKey: key });
      const prev = qc.getQueryData<Order[]>(key);
      qc.setQueryData<Order[]>(key, old =>
        old?.map(o => (o.id === id ? { ...o, starred: !o.starred } : o)));
      return { prev };
    },
    onError: (_e, _id, ctx) => qc.setQueryData(key, ctx?.prev), // rollback
    onSettled: () => qc.invalidateQueries({ queryKey: ['orders'] }),
  });
}

