// parse.worker.ts
/// <reference lib="webworker" />
// ↑ types self as a worker scope, not window
self.onmessage = async (e: MessageEvent<File>) => {
  const reader = e.data.stream()
    .pipeThrough(new TextDecoderStream())
    .getReader();
  let rows = 0;
  let rest = '';
  for (;;) {
    const { value, done } = await reader.read();
    if (done) break;
    const lines = (rest + value).split('\n');
    rest = lines.pop() ?? ''; // keep a half line for the next chunk
    rows += lines.length;
    self.postMessage({ type: 'progress', rows });
  }
  self.postMessage({ type: 'done', rows: rows + (rest ? 1 : 0) });
};

