'use client';
import { useRef } from 'react';

export function DeleteProject({ onConfirm }: { onConfirm: () => void }) {
  const ref = useRef<HTMLDialogElement>(null);

  return (
    <>
      <button type="button" onClick={() => ref.current?.showModal()}>
        Delete project
      </button>

      {/* showModal(): page behind becomes inert, Esc closes, focus returns to the opener */}
      <dialog ref={ref} aria-labelledby="del-title" aria-describedby="del-desc">
        <h2 id="del-title">Delete project?</h2>
        <p id="del-desc">This removes all files. It cannot be undone.</p>
        <form method="dialog">
          {/* showModal() focuses the first focusable element: keep Cancel first */}
          <button value="cancel">Cancel</button>
          <button value="delete" onClick={onConfirm}>Delete</button>
        </form>
      </dialog>
    </>
  );
}

